def solve(n):
    out=1
    for k in range(2,n+1):
        out*=k
    return out

def solve(a,b):
    a,b=abs(a),abs(b)
    while b:
        a,b=b,a%b
    return a

def solve(xs):
    seen=set()
    out=[]
    for x in xs:
        if x not in seen:
            seen.add(x)
            out.append(x)
    return out

def solve(s):
    counts={}
    for c in s:
        counts[c]=counts.get(c,0)+1
    return counts

def solve(n):
    steps=0
    while n!=1:
        n=n//2 if n%2==0 else 3*n+1
        steps+=1
    return steps

